PRAGMA foreign_keys = ON;
CREATE TABLE local_meta (id INTEGER PRIMARY KEY CHECK(id=1), local_schema_version INTEGER NOT NULL, runtime_version TEXT NOT NULL, sync_protocol_min TEXT NOT NULL, sync_protocol_max TEXT NOT NULL, client_instance_id TEXT NOT NULL, active_organization_id TEXT, created_at TEXT NOT NULL, last_successful_open_at TEXT, last_integrity_check_at TEXT, key_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE organization_context (organization_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, security_policy_version INTEGER NOT NULL, offline_lease_expires_at TEXT NOT NULL, last_bootstrap_at TEXT, last_successful_sync_at TEXT, current_cursor TEXT, minimum_runtime TEXT, compatibility_status TEXT NOT NULL DEFAULT 'COMPATIBLE');
CREATE TABLE membership_snapshot (organization_id TEXT NOT NULL, membership_id TEXT NOT NULL, user_id TEXT NOT NULL, lifecycle_state TEXT NOT NULL CHECK(lifecycle_state IN ('INVITED','ACTIVE','SUSPENDED','REVOKED')), role_scope_json TEXT NOT NULL, security_policy_version INTEGER NOT NULL, fetched_at TEXT NOT NULL, offline_lease_expires_at TEXT NOT NULL, PRIMARY KEY(organization_id,membership_id));
CREATE TABLE device_snapshot (organization_id TEXT NOT NULL, device_id TEXT NOT NULL, membership_id TEXT, state TEXT NOT NULL CHECK(state IN ('ACTIVE','SUSPENDED','REVOKED')), policy_version INTEGER NOT NULL, runtime_version TEXT NOT NULL, last_server_validation_at TEXT, last_sync_at TEXT, PRIMARY KEY(organization_id,device_id));
CREATE TABLE project_cache (organization_id TEXT NOT NULL, project_id TEXT NOT NULL, revision INTEGER NOT NULL, lifecycle_state TEXT NOT NULL, payload_json TEXT NOT NULL, received_at TEXT NOT NULL, PRIMARY KEY(organization_id,project_id));
CREATE TABLE template_package (organization_id TEXT NOT NULL, template_version_id TEXT NOT NULL, template_id TEXT NOT NULL, blueprint_json TEXT NOT NULL, blueprint_hash TEXT NOT NULL, schema_version TEXT NOT NULL, component_registry_version TEXT NOT NULL, minimum_runtime TEXT, integrity_verified INTEGER NOT NULL CHECK(integrity_verified IN (0,1)), downloaded_at TEXT NOT NULL, PRIMARY KEY(organization_id,template_version_id));
CREATE TABLE reference_dataset (organization_id TEXT NOT NULL, dataset_key TEXT NOT NULL, dataset_version TEXT NOT NULL, project_id TEXT, schema_version TEXT NOT NULL, content_hash TEXT, effective_at TEXT, downloaded_at TEXT NOT NULL, inactive INTEGER NOT NULL DEFAULT 0 CHECK(inactive IN (0,1)), PRIMARY KEY(organization_id,dataset_key,dataset_version));
CREATE TABLE reference_dataset_row (organization_id TEXT NOT NULL, dataset_key TEXT NOT NULL, dataset_version TEXT NOT NULL, row_key TEXT NOT NULL, value_json TEXT NOT NULL, inactive INTEGER NOT NULL DEFAULT 0 CHECK(inactive IN (0,1)), PRIMARY KEY(organization_id,dataset_key,dataset_version,row_key));
CREATE TABLE assignment_cache (organization_id TEXT NOT NULL, assignment_id TEXT NOT NULL, project_id TEXT NOT NULL, deployment_id TEXT NOT NULL, template_version_id TEXT NOT NULL, authoritative_revision INTEGER NOT NULL, lifecycle_state TEXT NOT NULL, conditions_json TEXT NOT NULL DEFAULT '[]', assignee_json TEXT NOT NULL, subject_json TEXT NOT NULL, due_at TEXT, priority TEXT, server_updated_at TEXT NOT NULL, received_at TEXT NOT NULL, local_execution_status TEXT NOT NULL DEFAULT 'NOT_STARTED', PRIMARY KEY(organization_id,assignment_id));
CREATE TABLE assignment_tombstone (organization_id TEXT NOT NULL, assignment_id TEXT NOT NULL, authoritative_revision INTEGER NOT NULL, tombstone_type TEXT NOT NULL CHECK(tombstone_type IN ('CANCELLED','REASSIGNED','ACCESS_REMOVED','COMPLETED_ELSEWHERE','DELETED_REFERENCE')), effective_at TEXT NOT NULL, received_at TEXT NOT NULL, reason_code TEXT, handling_status TEXT NOT NULL DEFAULT 'PENDING', PRIMARY KEY(organization_id,assignment_id,authoritative_revision));
CREATE TABLE submission_session (organization_id TEXT NOT NULL, session_id TEXT NOT NULL, assignment_id TEXT NOT NULL, assignment_revision_started INTEGER NOT NULL, template_version_id TEXT NOT NULL, lifecycle_state TEXT NOT NULL CHECK(lifecycle_state IN ('CREATED','IN_PROGRESS','COMPLETE','SUBMITTED','ABANDONED')), payload_json TEXT NOT NULL DEFAULT '{}', validation_json TEXT NOT NULL DEFAULT '{}', current_step_id TEXT, device_started_at TEXT, device_completed_at TEXT, device_submitted_at TEXT, last_local_save_at TEXT NOT NULL, local_revision INTEGER NOT NULL DEFAULT 0, owning_device_id TEXT NOT NULL, PRIMARY KEY(organization_id,session_id));
CREATE TABLE submission_attempt (organization_id TEXT NOT NULL, attempt_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, session_id TEXT NOT NULL, assignment_id TEXT NOT NULL, assignment_revision_used INTEGER NOT NULL, template_version_id TEXT NOT NULL, blueprint_hash TEXT NOT NULL, canonical_payload_json TEXT NOT NULL, payload_hash TEXT NOT NULL, evidence_manifest_json TEXT NOT NULL, membership_id TEXT, device_id TEXT NOT NULL, client_submitted_at TEXT, timezone TEXT, contract_version TEXT NOT NULL, created_at TEXT NOT NULL, server_submission_state TEXT CHECK(server_submission_state IS NULL OR server_submission_state IN ('RECEIVED','VALIDATING','ACCEPTED','REJECTED')), submission_id TEXT, server_outcome_at TEXT, rejection_code TEXT, PRIMARY KEY(organization_id,attempt_id), UNIQUE(organization_id,idempotency_key));
CREATE TABLE local_evidence (organization_id TEXT NOT NULL, attachment_id TEXT NOT NULL, assignment_id TEXT NOT NULL, session_id TEXT NOT NULL, field_id TEXT NOT NULL, evidence_type TEXT NOT NULL CHECK(evidence_type IN ('PHOTO','SIGNATURE','FILE_ATTACHMENT')), evidence_role TEXT NOT NULL CHECK(evidence_role IN ('ORIGINAL','DERIVATIVE')), parent_attachment_id TEXT, local_file_path TEXT NOT NULL, source_kind TEXT NOT NULL CHECK(source_kind IN ('CAMERA_CAPTURE','FILE_IMPORT','SIGNATURE_RENDER','SYSTEM_DERIVATIVE')), byte_size INTEGER NOT NULL CHECK(byte_size > 0), sha256 TEXT NOT NULL, claimed_mime_type TEXT, device_captured_at TEXT NOT NULL, timezone TEXT, gps_json TEXT, lifecycle_state TEXT NOT NULL CHECK(lifecycle_state IN ('LOCAL_CAPTURED','QUEUED_FOR_UPLOAD','UPLOADING','UPLOADED','BOUND','PROCESSING','READY','FAILED','RETAINED','PURGED')), created_by_membership_id TEXT, created_by_device_id TEXT NOT NULL, upload_id TEXT, server_integrity_state TEXT, server_binding_state TEXT, cleanup_eligible INTEGER NOT NULL DEFAULT 0 CHECK(cleanup_eligible IN (0,1)), PRIMARY KEY(organization_id,attachment_id), CHECK((evidence_role='ORIGINAL' AND parent_attachment_id IS NULL) OR (evidence_role='DERIVATIVE' AND parent_attachment_id IS NOT NULL)));
CREATE TABLE sync_inbox (organization_id TEXT NOT NULL, inbox_batch_id TEXT NOT NULL, prior_cursor TEXT NOT NULL, proposed_next_cursor TEXT NOT NULL, payload_hash TEXT NOT NULL, received_at TEXT NOT NULL, apply_state TEXT NOT NULL CHECK(apply_state IN ('RECEIVED','VALIDATED','APPLYING','APPLIED','FAILED')), error_code TEXT, PRIMARY KEY(organization_id,inbox_batch_id));
CREATE TABLE sync_inbox_item (organization_id TEXT NOT NULL, inbox_batch_id TEXT NOT NULL, delta_id TEXT NOT NULL, ordinal INTEGER NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, authoritative_revision INTEGER, change_type TEXT NOT NULL CHECK(change_type IN ('UPSERT','TOMBSTONE','OUTCOME','POLICY')), occurred_at TEXT NOT NULL, payload_json TEXT, apply_state TEXT NOT NULL CHECK(apply_state IN ('PENDING','APPLIED','IGNORED_STALE','FAILED','RECONCILIATION_REQUIRED')), apply_error TEXT, PRIMARY KEY(organization_id,delta_id));
CREATE TABLE sync_outbox (organization_id TEXT NOT NULL, operation_id TEXT NOT NULL, operation_type TEXT NOT NULL CHECK(operation_type IN ('EVIDENCE_UPLOAD_INIT','EVIDENCE_UPLOAD_PART','EVIDENCE_UPLOAD_FINALIZE','SUBMISSION_ATTEMPT_SEND','SYNC_ACK','RECONCILIATION_RESPONSE','DIAGNOSTIC_UPLOAD')), entity_type TEXT, entity_id TEXT, idempotency_key TEXT, payload_ref TEXT, priority INTEGER NOT NULL CHECK(priority BETWEEN 0 AND 3), state TEXT NOT NULL CHECK(state IN ('QUEUED','RUNNING','RETRY_WAIT','BLOCKED_DEPENDENCY','RECONCILIATION_REQUIRED','SUCCEEDED','FAILED_FINAL','CANCELLED_BY_POLICY')), attempt_count INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT, last_error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, terminal_outcome_ref TEXT, PRIMARY KEY(organization_id,operation_id));
CREATE TABLE sync_operation_dependency (organization_id TEXT NOT NULL, operation_id TEXT NOT NULL, depends_on_operation_id TEXT NOT NULL, required INTEGER NOT NULL DEFAULT 1 CHECK(required IN (0,1)), PRIMARY KEY(organization_id,operation_id,depends_on_operation_id));
CREATE TABLE sync_cursor (organization_id TEXT NOT NULL, device_id TEXT NOT NULL, current_cursor TEXT NOT NULL, last_applied_delta_id TEXT, server_generation TEXT, updated_at TEXT NOT NULL, PRIMARY KEY(organization_id,device_id));
CREATE TABLE sync_event (organization_id TEXT NOT NULL, sync_event_id TEXT NOT NULL, device_id TEXT NOT NULL, operation_id TEXT, event_kind TEXT NOT NULL, started_at TEXT, ended_at TEXT, outcome TEXT, retry_count INTEGER NOT NULL DEFAULT 0, bytes_count INTEGER, error_code TEXT, correlation_id TEXT, diagnostics_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(organization_id,sync_event_id));
CREATE TABLE reconciliation_case (organization_id TEXT NOT NULL, case_id TEXT NOT NULL, device_id TEXT NOT NULL, entity_type TEXT, entity_id TEXT, operation_id TEXT, conflict_type TEXT NOT NULL, local_revision INTEGER, server_revision INTEGER, local_state TEXT, server_state TEXT, created_at TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('INFO','WARNING','BLOCKING','CRITICAL')), allowed_actions_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('OPEN','AWAITING_USER','AWAITING_SERVER','RESOLVED','CLOSED_NO_ACTION','ESCALATED')), resolved_at TEXT, resolved_by TEXT, server_outcome_ref TEXT, PRIMARY KEY(organization_id,case_id));
CREATE TABLE reconciliation_action (organization_id TEXT NOT NULL, case_id TEXT NOT NULL, action_id TEXT NOT NULL, action_type TEXT NOT NULL, actor_ref TEXT, reason TEXT, created_at TEXT NOT NULL, PRIMARY KEY(organization_id,action_id));
CREATE TABLE diagnostic_event (organization_id TEXT NOT NULL, diagnostic_event_id TEXT NOT NULL, category TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('DEBUG','INFO','WARNING','ERROR','CRITICAL')), occurred_at TEXT NOT NULL, safe_metadata_json TEXT NOT NULL DEFAULT '{}', retention_class TEXT NOT NULL DEFAULT 'STANDARD', PRIMARY KEY(organization_id,diagnostic_event_id));
CREATE INDEX idx_outbox_runnable ON sync_outbox(organization_id,state,priority,next_attempt_at,created_at);
CREATE INDEX idx_inbox_batch ON sync_inbox_item(organization_id,inbox_batch_id,ordinal);
CREATE INDEX idx_assignment_revision ON assignment_cache(organization_id,assignment_id,authoritative_revision);
CREATE INDEX idx_evidence_session ON local_evidence(organization_id,session_id,lifecycle_state);


CREATE TRIGGER trg_submission_attempt_immutable BEFORE UPDATE ON submission_attempt
FOR EACH ROW WHEN
 NEW.idempotency_key<>OLD.idempotency_key OR NEW.session_id<>OLD.session_id OR NEW.assignment_id<>OLD.assignment_id OR NEW.assignment_revision_used<>OLD.assignment_revision_used OR NEW.template_version_id<>OLD.template_version_id OR NEW.blueprint_hash<>OLD.blueprint_hash OR NEW.canonical_payload_json<>OLD.canonical_payload_json OR NEW.payload_hash<>OLD.payload_hash OR NEW.evidence_manifest_json<>OLD.evidence_manifest_json OR NEW.device_id<>OLD.device_id OR NEW.contract_version<>OLD.contract_version OR NEW.created_at<>OLD.created_at
BEGIN SELECT RAISE(ABORT,'SUBMISSION_ATTEMPT_IMMUTABLE'); END;
CREATE TRIGGER trg_submitted_session_no_reopen BEFORE UPDATE ON submission_session
FOR EACH ROW WHEN OLD.lifecycle_state='SUBMITTED' AND (NEW.lifecycle_state<>'SUBMITTED' OR NEW.payload_json<>OLD.payload_json OR NEW.assignment_id<>OLD.assignment_id OR NEW.template_version_id<>OLD.template_version_id)
BEGIN SELECT RAISE(ABORT,'SUBMITTED_SESSION_IMMUTABLE'); END;
CREATE TRIGGER trg_evidence_identity_after_upload BEFORE UPDATE ON local_evidence
FOR EACH ROW WHEN OLD.lifecycle_state IN ('UPLOADED','BOUND','PROCESSING','READY','RETAINED','PURGED') AND (NEW.organization_id<>OLD.organization_id OR NEW.attachment_id<>OLD.attachment_id OR NEW.evidence_role<>OLD.evidence_role OR COALESCE(NEW.parent_attachment_id,'')<>COALESCE(OLD.parent_attachment_id,'') OR NEW.byte_size<>OLD.byte_size OR NEW.sha256<>OLD.sha256 OR NEW.local_file_path<>OLD.local_file_path)
BEGIN SELECT RAISE(ABORT,'EVIDENCE_IDENTITY_IMMUTABLE'); END;
